/* Contenu de l'app Apprensia, recopié par construire.py. Ne pas modifier ici. */
window.APPRENSIA = {"version":2,"chapitres":[{"id":"fonctionnement","rang":1,"sousTitre":"Le projecteur, ses réseaux et ses angles morts","titre":"Comment marche l'attention"},{"id":"ecrans","rang":2,"sousTitre":"Ce que coûtent les bascules et les notifications","titre":"Multitâche et écrans"},{"id":"idees-recues","rang":3,"sousTitre":"Ce que la recherche ne soutient pas","titre":"Idées reçues"},{"id":"apprendre","rang":4,"sousTitre":"Ce qui fait vraiment retenir","titre":"Apprendre et retenir"},{"id":"recentrer","rang":5,"sousTitre":"Faire une vraie pause, reprendre la main","titre":"Se recentrer"}],"notions":[{"id":"quatre-piliers","rang":1,"chapitre":"apprendre","titre":"Les quatre piliers de l'apprentissage","phrase":"Pour Stanislas Dehaene, on apprend grâce à quatre piliers : l'attention, l'engagement actif, le retour sur l'erreur et la consolidation.","recherche":["Dans *Apprendre !* (2018), le chercheur, professeur au Collège de France, fait la synthèse des sciences cognitives en quatre piliers.","L'attention filtre ce qui sera appris ; l'engagement actif (prédire, répondre) fait apprendre ; l'erreur, signalée vite, corrige ; la consolidation (sommeil, répétition) rend durable."],"nuances":["C'est un cadre de synthèse, pas une étude : chaque pilier renvoie à des travaux précis (effet test, répétition espacée, sommeil…)."],"auQuotidien":["Pour apprendre, ne restez pas passif : prédisez, répondez, expliquez.","Cherchez vite le retour sur vos erreurs, et dormez : c'est pendant le sommeil que se consolide ce qu'on a appris."],"liees":["effet-test","repetition-espacee"],"experience":null,"sources":["Dehaene, S. (2018). Apprendre ! Les talents du cerveau, le défi des machines. Odile Jacob."]},{"id":"effet-test","rang":2,"chapitre":"apprendre","titre":"L'effet test","phrase":"Chercher dans sa mémoire fait mieux retenir que relire, surtout à long terme.","recherche":["En 2006, Henry Roediger et Jeffrey Karpicke font lire un texte, puis le relire ou se tester. Cinq minutes après, la relecture semble gagner ; une semaine après, ceux qui se sont testés retiennent 61 %, contre 40 % pour ceux qui ont relu."],"nuances":["Relire donne une illusion de maîtrise : le texte paraît familier, donc « su ».","Le test n'a pas besoin d'être noté : c'est l'effort de rappel qui compte."],"auQuotidien":["Après avoir lu, fermez le livre et écrivez ce dont vous vous souvenez.","C'est exactement ce que fait l'onglet « S'entraîner » de l'app Apprensia."],"liees":["pretest","repetition-espacee"],"experience":null,"sources":["Roediger, H. L. et Karpicke, J. D. (2006). Test-enhanced learning: taking memory tests improves long-term retention. Psychological Science, 17(3), 249-255."]},{"id":"pretest","rang":3,"chapitre":"apprendre","titre":"L'effet de prétest","phrase":"Se poser une question avant d'apprendre la réponse aide à la retenir, même quand on s'est trompé.","recherche":["En 2009, Lindsey Richland, Nate Kornell et Liche Sean Kao montrent, dans cinq expériences, que répondre à des questions avant de lire un texte fait mieux retenir, même pour les questions ratées au départ."],"nuances":["L'effet tient surtout si la bonne réponse arrive rapidement après.","Se tromper à un prétest fait partie du jeu : ce n'est pas un échec."],"auQuotidien":["Avant de lire un chapitre, essayez de répondre aux questions de fin de chapitre.","Avant une réunion, notez ce que vous pensez qu'elle va conclure."],"liees":["effet-test","projecteur"],"experience":null,"sources":["Richland, L. E., Kornell, N. et Kao, L. S. (2009). The pretesting effect: do unsuccessful retrieval attempts enhance learning? Journal of Experimental Psychology: Applied, 15(3), 243-257."]},{"id":"charge-cognitive","rang":4,"chapitre":"apprendre","titre":"La charge cognitive","phrase":"La mémoire de travail est limitée : ce qui la surcharge (consignes multiples, informations inutiles) laisse moins de place pour apprendre.","recherche":["En 1988, John Sweller montre que résoudre des problèmes par essais et erreurs peut saturer la mémoire de travail et gêner l'apprentissage, et que des exemples résolus aident les débutants.","En 2003, Slava Kalyuga et ses collègues décrivent l'« effet de renversement de l'expertise » : ce qui aide un débutant peut gêner quelqu'un de plus avancé."],"nuances":["C'est une théorie très utilisée, parfois simplifiée à l'excès : un cadre, pas une loi.","La charge dépend de ce qu'on sait déjà."],"auQuotidien":["Une chose à la fois : notez les consignes plutôt que de les garder en tête.","Retirez l'inutile, pas le difficile : la difficulté qui fait réfléchir est utile."],"liees":["stroop","styles-apprentissage"],"experience":null,"sources":["Sweller, J. (1988). Cognitive load during problem solving: effects on learning. Cognitive Science, 12(2), 257-285.","Kalyuga, S., Ayres, P., Chandler, P. et Sweller, J. (2003). The expertise reversal effect. Educational Psychologist, 38(1), 23-31."]},{"id":"repetition-espacee","rang":5,"chapitre":"apprendre","titre":"La répétition espacée","phrase":"Revoir une notion plusieurs fois, espacées dans le temps, fait bien mieux retenir que tout revoir d'un coup.","recherche":["En 2006, Nicholas Cepeda et ses collègues analysent 839 comparaisons dans 317 expériences : espacer bat masser, et l'intervalle idéal grandit avec la durée pendant laquelle on veut retenir."],"nuances":["Espacer paraît moins efficace sur le moment, parce qu'on a un peu oublié : c'est justement ce qui aide.","Cela se combine très bien avec l'effet test."],"auQuotidien":["Pour un examen dans un mois : revoir après un jour, une semaine, puis deux semaines.","Les questions de l'app Apprensia reviennent ainsi : plus souvent quand vous vous trompez, plus rarement quand vous savez."],"liees":["effet-test","quatre-piliers"],"experience":null,"sources":["Cepeda, N. J., Pashler, H., Vul, E., Wixted, J. T. et Rohrer, D. (2006). Distributed practice in verbal recall tasks. Psychological Bulletin, 132(3), 354-380."]},{"id":"alternance","rang":1,"chapitre":"ecrans","titre":"Le coût de l'alternance","phrase":"Faire « deux choses à la fois », quand elles sont exigeantes, c'est en réalité alterner, et chaque bascule coûte du temps et des erreurs.","recherche":["En 2001, Joshua Rubinstein, David Meyer et Jeffrey Evans montrent qu'alterner entre deux tâches coûte du temps, davantage quand elles sont complexes ou peu familières : il faut « recharger » les règles de la nouvelle tâche.","En 2003, Stephen Monsell en fait la synthèse : le coût persiste même quand on sait à l'avance quelle tâche arrive."],"nuances":["En laboratoire, une bascule coûte une fraction de seconde ; mais ces coûts s'additionnent, et les erreurs aussi.","Une activité automatique (marcher) et une activité exigeante (parler) se combinent bien. C'est entre deux activités exigeantes que ça coince."],"auQuotidien":["Regroupez les tâches semblables (tous les mails d'un coup) plutôt que de les intercaler.","Une musique sans paroles gêne peu ; des paroles gênent la lecture, parce qu'elles sollicitent le langage."],"liees":["residu","multitache-numerique"],"experience":"multitache","sources":["Rubinstein, J. S., Meyer, D. E. et Evans, J. E. (2001). Executive control of cognitive processes in task switching. Journal of Experimental Psychology: Human Perception and Performance, 27(4), 763-797.","Monsell, S. (2003). Task switching. Trends in Cognitive Sciences, 7(3), 134-140."]},{"id":"residu","rang":2,"chapitre":"ecrans","titre":"Le résidu attentionnel","phrase":"Quand on passe à une nouvelle tâche en laissant la précédente inachevée, une partie de l'attention reste accrochée à l'ancienne, et on travaille moins bien sur la nouvelle.","recherche":["En 2009, Sophie Leroy montre que des participants qui changent de tâche en laissant la première inachevée réussissent moins bien la suivante que ceux qui l'ont terminée.","En 2018, avec Theresa Glomb, elle montre qu'écrire en une phrase où l'on reprendra réduit ce résidu."],"nuances":["Ce sont des études sur des adultes au travail.","À ne pas confondre avec l'« effet Zeigarnik » (mieux se souvenir des tâches inachevées), qui ne se réplique pas."],"auQuotidien":["Avant de passer à autre chose, notez en une phrase où vous en êtes et ce que vous ferez ensuite.","Entre deux activités, un court rituel (ranger, respirer, noter) aide à « fermer la porte »."],"liees":["alternance","notifications"],"experience":null,"sources":["Leroy, S. (2009). Why is it so hard to do my work? Organizational Behavior and Human Decision Processes, 109(2), 168-181.","Leroy, S. et Glomb, T. M. (2018). Tasks interrupted. Organization Science, 29(3), 380-397."]},{"id":"multitache-numerique","rang":3,"chapitre":"ecrans","titre":"Le multitâche numérique en cours","phrase":"Faire autre chose sur un écran pendant un cours fait baisser les résultats de celui qui le fait, et de ses voisins.","recherche":["En 2013, Faria Sana, Tina Weston et Nicholas Cepeda font suivre un cours simulé à des étudiants : ceux qui font d'autres tâches sur leur ordinateur obtiennent 11 % de moins au test ; ceux qui voient seulement l'écran d'un voisin, 17 % de moins."],"nuances":["L'étude porte sur des étudiants, dans un cours simulé.","Pour la prise de notes sur ordinateur elle-même, les résultats sont plus discutés."],"auQuotidien":["En réunion ou en cours, un écran ouvert sur autre chose coûte aussi aux personnes assises à côté.","Fermer les onglets sans rapport avant de commencer évite la tentation."],"liees":["alternance","notifications"],"experience":null,"sources":["Sana, F., Weston, T. et Cepeda, N. J. (2013). Laptop multitasking hinders classroom learning for both users and nearby peers. Computers & Education, 62, 24-31."]},{"id":"notifications","rang":4,"chapitre":"ecrans","titre":"Le coût d'une notification","phrase":"Recevoir une notification, même sans la regarder, perturbe une tâche qui demande de l'attention.","recherche":["En 2015, Cary Stothart, Ainsley Mitchum et Courtney Yehnert montrent que des participants qui reçoivent un appel ou un message pendant une tâche d'attention, sans y répondre, font plus d'erreurs, d'une ampleur comparable à ceux qui utilisent activement leur téléphone."],"nuances":["C'est une tâche de laboratoire.","L'idée que la simple présence du téléphone sur la table « vide le cerveau » a des réplications discutées : on ne peut pas l'affirmer."],"auQuotidien":["Pendant un travail exigeant : mode silencieux ou mode avion, et téléphone hors de vue.","Désactivez les notifications des applications qui n'ont rien d'urgent."],"liees":["residu","economie-attention"],"experience":null,"sources":["Stothart, C., Mitchum, A. et Yehnert, C. (2015). The attentional cost of receiving a cell phone notification. Journal of Experimental Psychology: Human Perception and Performance, 41(4), 893-897."]},{"id":"economie-attention","rang":5,"chapitre":"ecrans","titre":"L'économie de l'attention","phrase":"Quand l'information devient abondante, c'est l'attention qui devient rare, et donc convoitée.","recherche":["En 1971, l'économiste Herbert Simon, futur prix Nobel, écrit qu'« une abondance d'information crée une pauvreté d'attention ».","Aujourd'hui, de nombreux produits numériques sont conçus pour capter et retenir l'attention le plus longtemps possible."],"nuances":["C'est un cadre d'analyse, pas un résultat expérimental.","Le cerveau n'a pas changé en une génération ; c'est l'environnement qui sollicite davantage."],"auQuotidien":["Choisir ce qui mérite votre attention est une décision : faites-la avant d'ouvrir une application, pas après.","Votre attention n'est pas cassée : réglez votre environnement, elle suivra."],"liees":["poisson-rouge","notifications"],"experience":null,"sources":["Simon, H. A. (1971). Designing organizations for an information-rich world. Dans M. Greenberger (dir.), Computers, Communications, and the Public Interest. Johns Hopkins Press."]},{"id":"trois-reseaux","rang":1,"chapitre":"fonctionnement","titre":"Les trois réseaux de l'attention","phrase":"L'attention n'est pas une capacité unique : trois réseaux travaillent ensemble, l'alerte (être prêt), l'orientation (diriger le projecteur) et le contrôle (tenir malgré les distractions).","recherche":["Michael Posner et Steven Petersen ont proposé ce modèle en 1990, puis en ont fait le bilan vingt ans plus tard : trois réseaux en partie distincts par leurs régions cérébrales et leurs messagers chimiques.","Un test, l'*Attention Network Test*, mesure les trois séparément chez une même personne."],"nuances":["C'est un modèle : les trois réseaux interagissent en permanence, ce ne sont pas trois boutons indépendants.","Le contrôle, très lié au cortex préfrontal, continue de mûrir pendant l'adolescence."],"auQuotidien":["Fatigué, votre « alerte » baisse : ce n'est pas le moment de la tâche la plus exigeante.","Avant de travailler, décidez où pointer le projecteur : une seule tâche, nommée.","Plutôt que de compter sur la volonté pour « tenir », retirez ce qui distrait."],"liees":["projecteur","stroop"],"experience":null,"sources":["Petersen, S. E. et Posner, M. I. (2012). The attention system of the human brain: 20 years after. Annual Review of Neuroscience, 35, 73-89.","Posner, M. I. et Petersen, S. E. (1990). The attention system of the human brain. Annual Review of Neuroscience, 13, 25-42."]},{"id":"projecteur","rang":2,"chapitre":"fonctionnement","titre":"Le projecteur de Posner","phrase":"Savoir à l'avance où regarder accélère la réponse ; un indice trompeur la ralentit. L'attention se déplace comme un projecteur, même sans bouger les yeux.","recherche":["En 1980, Michael Posner montre qu'un indice annonçant où apparaîtra une cible fait répondre plus vite ; un indice invalide fait répondre plus lentement. Les écarts se comptent en dizaines de millisecondes.","Il distingue l'orientation que l'on décide (on choisit où regarder) de celle qui nous est imposée (un bruit, un mouvement, une vibration)."],"nuances":["Ce sont des effets de laboratoire, mesurés en millisecondes.","Leur transposition à la vie courante (annoncer un plan, préparer ce qu'on va chercher) est une analogie raisonnable, pas une preuve directe."],"auQuotidien":["Avant de lire un chapitre, parcourez les titres : vous saurez où poser votre attention.","Une vibration de téléphone oriente votre projecteur sans votre accord : éloignez ce qui capte malgré vous."],"liees":["trois-reseaux","cecite"],"experience":null,"sources":["Posner, M. I. (1980). Orienting of attention. Quarterly Journal of Experimental Psychology, 32(1), 3-25."]},{"id":"stroop","rang":3,"chapitre":"fonctionnement","titre":"L'effet Stroop","phrase":"Dire la couleur de l'encre d'un mot de couleur qui ne correspond pas prend nettement plus de temps : la lecture est automatique, il faut la freiner, et ce freinage est un effort.","recherche":["En 1935, John Ridley Stroop montre que nommer la couleur de mots incongruents (le mot ROUGE écrit en bleu) est bien plus lent que nommer la couleur de simples rectangles.","En 1991, une synthèse d'un demi-siècle de recherche (Colin MacLeod) en fait l'un des effets les plus robustes de la psychologie."],"nuances":["L'effet mesure le contrôle inhibiteur : il suppose de savoir lire couramment.","S'entraîner au Stroop améliore… le Stroop. Les programmes d'« entraînement cérébral » transfèrent peu vers la vie réelle (Simons et al., 2016)."],"auQuotidien":["Résister à une distraction n'est pas gratuit : c'est un effort qui fatigue au fil de la journée.","Plutôt que de lutter contre une distraction, supprimez-la : c'est moins coûteux que de la freiner en permanence."],"liees":["trois-reseaux","charge-cognitive"],"experience":"stroop","sources":["Stroop, J. R. (1935). Studies of interference in serial verbal reactions. Journal of Experimental Psychology, 18(6), 643-662.","MacLeod, C. M. (1991). Half a century of research on the Stroop effect. Psychological Bulletin, 109(2), 163-203.","Simons, D. J. et al. (2016). Do « brain-training » programs work? Psychological Science in the Public Interest, 17(3), 103-186."]},{"id":"cecite","rang":4,"chapitre":"fonctionnement","titre":"La cécité d'inattention","phrase":"Quand notre attention est occupée, on peut ne pas voir un objet pourtant bien visible : on voit ce qu'on cherche.","recherche":["En 1999, Daniel Simons et Christopher Chabris demandent de compter des passes de basket : 56 % des participants ne voient pas une personne déguisée en gorille traverser la scène.","En 2001, Steven Most et ses collègues montrent que la ressemblance compte : en suivant des formes blanches, 6 % seulement remarquent une croix noire, contre 94 % quand elle est blanche."],"nuances":["Plus un objet ressemble à ce qu'on ignore, moins on le voit.","Ceux qui voient l'objet inattendu ne sont pas « plus attentifs » : dans l'étude de 2001, ils ne comptaient pas mieux que les autres.","La démonstration ne fonctionne qu'une fois : quand on sait, on regarde autrement."],"auQuotidien":["En voiture, au téléphone, on peut regarder la route sans voir ce qui s'y passe.","Dans une recherche, un texte, un problème : on trouve surtout ce qu'on sait chercher. Changer de question fait voir autre chose."],"liees":["projecteur","vagabondage"],"experience":"cecite","sources":["Simons, D. J. et Chabris, C. F. (1999). Gorillas in our midst. Perception, 28, 1059-1074.","Most, S. B., Simons, D. J., Scholl, B. J., Jimenez, R., Clifford, E. et Chabris, C. F. (2001). How not to be seen. Psychological Science, 12(1), 9-17."]},{"id":"vagabondage","rang":5,"chapitre":"fonctionnement","titre":"Le vagabondage de l'esprit","phrase":"L'esprit quitte souvent ce qu'on est en train de faire, et de plus en plus pendant une écoute longue et passive.","recherche":["En 2010, Matthew Killingsworth et Daniel Gilbert interrogent 2 250 adultes à des moments aléatoires grâce à une application : leur esprit est ailleurs 46,9 % du temps éveillé, et ils se disent moins heureux quand il vagabonde.","En 2012, Evan Risko et ses collègues interrompent un cours vidéo d'une heure par des « sondes » : le vagabondage augmente au fil du cours, et ceux qui vagabondent retiennent moins bien le contenu."],"nuances":["Vagabonder n'est pas toujours négatif : cela sert aussi à planifier et à créer.","Ces mesures reposent sur ce que les gens déclarent."],"auQuotidien":["Pendant une vidéo ou une réunion longue, prenez des notes ou posez-vous une question : l'écoute active ramène l'esprit.","Remarquer qu'on était ailleurs, puis revenir, c'est déjà reprendre la main."],"liees":["mythe-10-minutes","pauses-actives"],"experience":null,"sources":["Killingsworth, M. A. et Gilbert, D. T. (2010). A wandering mind is an unhappy mind. Science, 330, 932.","Risko, E. F. et al. (2012). Everyday attention: variation in mind wandering and memory in a lecture. Applied Cognitive Psychology, 26, 234-242."]},{"id":"styles-apprentissage","rang":1,"chapitre":"idees-recues","titre":"Les styles d'apprentissage","phrase":"Apprendre selon son « style » (visuel, auditif, kinesthésique) n'améliore pas l'apprentissage : c'est le neuromythe le plus répandu.","recherche":["En 2008, Harold Pashler et ses collègues expliquent ce qu'il faudrait montrer : que les « visuels » apprennent mieux avec une méthode, et les « auditifs » avec une autre. Presque aucune étude n'utilise ce protocole, et celles qui le font ne trouvent pas ce croisement.","C'est pourtant très cru : 93 % des enseignants interrogés au Royaume-Uni et 96 % aux Pays-Bas y croyaient (Dekker et al., 2012)."],"nuances":["Chacun a des préférences, c'est vrai ; mais s'y plier n'aide pas à apprendre.","Ce qui aide tout le monde : adapter la forme au contenu, et combiner mots et images."],"auQuotidien":["Une carte se regarde, une langue s'écoute, un geste se pratique : choisissez selon ce que vous apprenez, pas selon « votre style ».","Associez un schéma à ce que vous lisez : cela aide, quel que soit votre profil."],"liees":["neuromythes","charge-cognitive"],"experience":null,"sources":["Pashler, H., McDaniel, M., Rohrer, D. et Bjork, R. (2008). Learning styles: concepts and evidence. Psychological Science in the Public Interest, 9(3), 105-119.","Dekker, S., Lee, N. C., Howard-Jones, P. et Jolles, J. (2012). Neuromyths in education: prevalence and predictors of misconceptions among teachers. Frontiers in Psychology, 3, 429."]},{"id":"mythe-10-minutes","rang":2,"chapitre":"idees-recues","titre":"Le mythe des 10 minutes d'attention","phrase":"« L'attention chute après 10 à 15 minutes » : les études citées ne le soutiennent pas. Mais l'esprit vagabonde davantage pendant une écoute longue et passive.","recherche":["En 2007, Karen Wilson et James Korn relisent les études à l'origine du chiffre : elles apportent peu de soutien à une chute à 10-15 minutes.","En 2016, Neil Bradbury arrive à la même conclusion : la plus grande variation vient de l'enseignant et de la situation, pas d'une horloge interne.","En revanche, le vagabondage augmente au fil d'un cours passif (Risko et al., 2012)."],"nuances":["Le chiffre circule de livre en livre, souvent sans source.","Le bon message n'est pas « tout découper en tranches de 10 minutes », mais « varier »."],"auQuotidien":["Il n'y a pas de minuterie qui sonne : observez plutôt quand vous décrochez, et changez d'activité à ce moment-là.","Rendez l'écoute active : questions, notes, reformulation."],"liees":["vagabondage","rythmes-52-17"],"experience":null,"sources":["Wilson, K. et Korn, J. H. (2007). Attention during lectures: beyond ten minutes. Teaching of Psychology, 34(2), 85-89.","Bradbury, N. A. (2016). Attention span during lectures: 8 seconds, 10 minutes, or more? Advances in Physiology Education, 40, 509-513."]},{"id":"poisson-rouge","rang":3,"chapitre":"idees-recues","titre":"Le mythe du poisson rouge","phrase":"« 8 secondes d'attention, moins qu'un poisson rouge » : ce chiffre n'a aucune source scientifique.","recherche":["Il a été popularisé en 2015 par un rapport marketing de Microsoft Canada, qui le reprenait d'un site de statistiques.","Une enquête de la BBC (2017) n'a retrouvé aucune étude derrière, ni pour les humains, ni pour les poissons rouges."],"nuances":["La « durée d'attention » n'est pas une constante : elle dépend de la tâche, de l'intérêt et de l'environnement.","Ce qui a changé, c'est l'environnement, avec bien plus de sollicitations conçues pour capter."],"auQuotidien":["Si vous vous sentez « incapable de vous concentrer », regardez d'abord ce qui vous entoure : c'est là qu'on agit le plus facilement."],"liees":["economie-attention","neuromythes"],"experience":null,"sources":["Maybin, S. (2017). Busting the attention span myth. BBC News, 10 mars 2017."]},{"id":"rythmes-52-17","rang":4,"chapitre":"idees-recues","titre":"Les rythmes de 90 minutes et le 52/17","phrase":"Travailler par cycles de 90 minutes, ou « 52 minutes puis 17 de pause » : des idées populaires, mais peu prouvées pendant la journée.","recherche":["Le cycle d'environ 90 minutes décrit par Nathaniel Kleitman est bien établi pendant le sommeil ; son prolongement pendant l'éveil est beaucoup moins solide.","Le « 52/17 » vient de DeskTime (2014), une application de suivi du temps : ses utilisateurs les plus productifs travaillaient environ 52 minutes puis s'arrêtaient environ 17. Ce sont des données d'observation, non publiées dans une revue scientifique, qui ne montrent pas que ce rythme cause la productivité."],"nuances":["Ce qui est solide : faire des pauses, et les pauses actives.","Une méthode comme le Pomodoro (25 minutes) est une méthode d'organisation, pas un résultat de recherche : elle peut aider, sans chiffre magique."],"auQuotidien":["Choisissez un rythme qui vous convient, et testez-le une semaine plutôt que de suivre un chiffre.","Annoncez-vous la fin d'une séance : savoir quand on s'arrête aide à tenir."],"liees":["mythe-10-minutes","pauses-actives"],"experience":null,"sources":["Kleitman, N. (1982). Basic rest-activity cycle — 22 years later. Sleep, 5(4), 311-317.","DeskTime (2014), analyse publiée sur le blog de l'entreprise, non évaluée par des pairs."]},{"id":"neuromythes","rang":5,"chapitre":"idees-recues","titre":"Les neuromythes","phrase":"Des idées fausses sur le cerveau circulent largement, y compris chez les plus passionnés de neurosciences.","recherche":["En 2012, Sanne Dekker et ses collègues interrogent 242 enseignants au Royaume-Uni et aux Pays-Bas : ils croient en moyenne 49 % des neuromythes, alors qu'ils répondent juste à environ 70 % des questions de connaissances générales.","Surprise : plus de connaissances générales sur le cerveau prédit davantage de croyance aux neuromythes."],"nuances":["L'échantillon est fait de volontaires intéressés par les neurosciences.","Les mythes les plus crus sont souvent liés à des programmes vendus « basés sur le cerveau »."],"auQuotidien":["Devant une affirmation sur le cerveau, demandez la source, et vérifiez qu'elle est publiée.","Méfiez-vous des méthodes qui promettent d'« activer » une partie du cerveau."],"liees":["styles-apprentissage","poisson-rouge"],"experience":null,"sources":["Dekker, S., Lee, N. C., Howard-Jones, P. et Jolles, J. (2012). Neuromyths in education: prevalence and predictors of misconceptions among teachers. Frontiers in Psychology, 3, 429."]},{"id":"restauration","rang":1,"chapitre":"recentrer","titre":"La restauration attentionnelle","phrase":"L'attention qu'on dirige se fatigue ; des environnements naturels, qui attirent l'attention sans effort, aideraient à la recharger.","recherche":["En 1995, Stephen Kaplan propose la théorie de la restauration attentionnelle : un environnement restaure s'il offre une « fascination douce », un éloignement du quotidien, une étendue et une compatibilité avec ce qu'on veut faire.","En 2008, Marc Berman et ses collègues trouvent de meilleures performances d'attention après une promenade de 50 minutes dans un parc qu'après une promenade en ville."],"nuances":["Les réplications sont mitigées : une étude de 2023 trouve un effet sur l'humeur, mais pas sur la concentration.","C'est une piste intéressante pour les pauses, pas une certitude."],"auQuotidien":["Pour une vraie pause, regardez dehors ou marchez plutôt que de faire défiler un écran, qui sollicite encore l'attention."],"liees":["pauses-actives","economie-attention"],"experience":null,"sources":["Kaplan, S. (1995). The restorative benefits of nature: toward an integrative framework. Journal of Environmental Psychology, 15, 169-182.","Berman, M. G., Jonides, J. et Kaplan, S. (2008). The cognitive benefits of interacting with nature. Psychological Science, 19(12), 1207-1212."]},{"id":"pauses-actives","rang":2,"chapitre":"recentrer","titre":"Les pauses actives","phrase":"De courtes pauses en mouvement augmentent ensuite le temps passé concentré sur la tâche.","recherche":["En 2006, Matthew Mahar et ses collègues introduisent de courtes activités physiques en classe, à l'école primaire : après ces pauses, les élèves passent plus de temps concentrés sur leur travail, surtout ceux qui l'étaient le moins."],"nuances":["L'étude porte sur des enfants : pour les adultes, c'est une piste solide, pas une garantie.","À ne pas confondre avec *Brain Gym*, un programme commercial dont les promesses sont des neuromythes."],"auQuotidien":["Toutes les heures environ, levez-vous deux minutes : marchez, étirez-vous, puis reprenez.","Une pause courte, annoncée et cadrée relance mieux qu'une pause qui s'éternise sur un écran."],"liees":["restauration","rythmes-52-17"],"experience":null,"sources":["Mahar, M. T. et al. (2006). Effects of a classroom-based program on physical activity and on-task behavior. Medicine & Science in Sports & Exercise, 38(12), 2086-2094."]},{"id":"soupir-cyclique","rang":3,"chapitre":"recentrer","titre":"Le soupir cyclique","phrase":"Deux inspirations par le nez, puis une longue expiration par la bouche : cinq minutes par jour ont amélioré l'humeur dans un essai récent.","recherche":["En 2023, Melis Yilmaz Balban et ses collègues comparent, chez 108 adultes et pendant un mois, trois exercices de respiration de cinq minutes par jour à la méditation de pleine conscience : le soupir cyclique donne la plus forte amélioration de l'humeur et la plus forte baisse de la fréquence respiratoire."],"nuances":["Un seul essai, avec des adultes, et une humeur que les participants déclarent eux-mêmes.","Aucun effet démontré sur la concentration : c'est un outil pour se poser."],"auQuotidien":["Avant une tâche exigeante ou après une contrariété : une minute de soupir cyclique.","Si vous vous sentez mal à l'aise, respirez normalement : on ne force jamais un exercice de respiration."],"liees":["ancrage-54321","restauration"],"experience":"souffle","sources":["Balban, M. Y. et al. (2023). Brief structured respiration practices enhance mood and reduce physiological arousal. Cell Reports Medicine, 4(1), 100895."]},{"id":"ancrage-54321","rang":4,"chapitre":"recentrer","titre":"L'ancrage 5-4-3-2-1","phrase":"Nommer cinq choses vues, quatre sons, trois contacts, deux odeurs et un goût, pour revenir dans l'instant quand les pensées s'emballent.","recherche":["C'est une technique d'ancrage issue de la gestion du stress et de l'anxiété. Elle a peu d'études contrôlées qui lui soient propres.","Son principe est cohérent avec ce qu'on sait : ramener l'attention vers l'extérieur interrompt la rumination."],"nuances":["C'est une pratique, présentée comme telle, sans promesse d'effet mesuré.","Ce n'est pas un soin : en cas de détresse, parlez-en à un professionnel de santé."],"auQuotidien":["Avant un examen, un entretien, une prise de parole : deux minutes de 5-4-3-2-1.","Essayez-le plusieurs fois avant de juger s'il vous sert."],"liees":["soupir-cyclique","vagabondage"],"experience":"ancrage","sources":["Pas de référence unique : technique d'ancrage transmise en thérapie et en gestion du stress."]}],"experiences":[{"dureeSecondes":90,"id":"stroop","notion":"stroop","promesse":"Sentez l'effort qu'il faut pour freiner la lecture.","titre":"Le Stroop"},{"dureeSecondes":60,"id":"cecite","notion":"cecite","promesse":"Comptez des rebonds… et découvrez ce que vous n'avez pas vu.","titre":"La croix invisible"},{"dureeSecondes":90,"id":"multitache","notion":"alternance","promesse":"Mesurez ce que coûte une bascule entre deux tâches.","titre":"Le multitâche"},{"dureeSecondes":63,"id":"souffle","notion":"soupir-cyclique","promesse":"Une minute guidée pour vous poser.","titre":"Le soupir cyclique"},{"dureeSecondes":100,"id":"ancrage","notion":"ancrage-54321","promesse":"Revenez dans l'instant, sens par sens.","titre":"5-4-3-2-1"}],"questions":[{"bonne":"Un croisement : chaque « style » apprend mieux avec « sa » méthode","explication":"Presque aucune étude n'utilise ce protocole, et celles qui le font ne trouvent pas le croisement.","id":"q-styles-apprentissage-1","mauvaises":["Que les gens ont des préférences","Que les « visuels » aiment les images"],"notion":"styles-apprentissage","texte":"Que faudrait-il montrer pour valider les styles d'apprentissage ?"},{"bonne":"93 %","explication":"93 % au Royaume-Uni, 96 % aux Pays-Bas.","id":"q-styles-apprentissage-2","mauvaises":["33 %","64 %"],"notion":"styles-apprentissage","texte":"Quelle part des enseignants britanniques croyaient aux styles d'apprentissage (Dekker, 2012) ?"},{"bonne":"Les études citées le soutiennent peu","explication":"La plus grande variation vient de l'enseignant et de la situation.","id":"q-mythe-10-minutes-1","mauvaises":["C'est confirmé","C'est plutôt 20 minutes"],"notion":"mythe-10-minutes","texte":"« L'attention chute après 10 à 15 minutes » : que concluent Wilson et Korn (2007) ?"},{"bonne":"Varier les activités","explication":"Il n'y a pas de minuterie interne, mais une écoute passive qui use.","id":"q-mythe-10-minutes-2","mauvaises":["Découper tout en tranches de 10 minutes","Faire une pause toutes les 10 minutes"],"notion":"mythe-10-minutes","texte":"Quel message garder à la place ?"},{"bonne":"D'un rapport marketing, sans étude derrière","explication":"Microsoft Canada l'a popularisé en 2015 ; la BBC n'a retrouvé aucune source.","id":"q-poisson-rouge-1","mauvaises":["D'une étude de Harvard","D'une étude sur des poissons rouges"],"notion":"poisson-rouge","texte":"D'où vient le chiffre de « 8 secondes d'attention » ?"},{"bonne":"La tâche et l'environnement","explication":"La durée d'attention n'est pas une constante : elle varie avec ce qu'on fait et ce qui nous entoure.","id":"q-poisson-rouge-2","mauvaises":["L'âge, surtout","Un chiffre fixe pour chaque génération"],"notion":"poisson-rouge","texte":"Qu'est-ce qui influence le plus la durée pendant laquelle on reste attentif ?"},{"bonne":"Des données d'une application, observationnelles","explication":"Une corrélation ne prouve pas que le rythme cause la productivité.","id":"q-rythmes-52-17-1","mauvaises":["Une étude publiée et contrôlée","Une loi de la chronobiologie"],"notion":"rythmes-52-17","texte":"Le « 52 minutes de travail, 17 de pause » de DeskTime, c'est…"},{"bonne":"Pendant le sommeil","explication":"Pendant l'éveil, les données sont trop faibles pour en faire une règle.","id":"q-rythmes-52-17-2","mauvaises":["Pendant la journée de travail","Nulle part"],"notion":"rythmes-52-17","texte":"Le cycle d'environ 90 minutes de Kleitman est bien établi…"},{"bonne":"49 %","explication":"La moitié, alors qu'ils répondaient juste à environ 70 % des questions générales.","id":"q-neuromythes-1","mauvaises":["15 %","85 %"],"notion":"neuromythes","texte":"En moyenne, quelle part des neuromythes les enseignants de Dekker et al. (2012) croyaient-ils ?"},{"bonne":"prédisait davantage de neuromythes","explication":"L'enthousiasme pour les neurosciences rend vulnérable aux fausses applications.","id":"q-neuromythes-2","mauvaises":["protégeait des neuromythes","n'avait aucun lien"],"notion":"neuromythes","texte":"Dans cette étude, avoir plus de connaissances sur le cerveau…"}],"glossaire":[{"definition":"Le réseau de l'attention qui nous rend prêts à réagir. Il baisse avec la fatigue.","id":"alerte","mot":"Alerte","notions":["trois-reseaux"]},{"definition":"Passer d'une tâche à une autre. Entre deux tâches exigeantes, chaque bascule coûte du temps et des erreurs.","id":"alternance","mot":"Alternance","notions":["alternance"]},{"definition":"Une technique pour revenir dans l'instant en portant l'attention sur ses sens, comme le 5-4-3-2-1.","id":"ancrage","mot":"Ancrage","notions":["ancrage-54321"]},{"definition":"Un test qui mesure séparément, chez une même personne, l'alerte, l'orientation et le contrôle.","id":"attention-network-test","mot":"Attention Network Test","notions":["trois-reseaux"]},{"definition":"Ne pas voir un objet bien visible, parce que l'attention est occupée ailleurs.","id":"cecite-d-inattention","mot":"Cécité d'inattention","notions":["cecite"]},{"definition":"Ce que demande une tâche à la mémoire de travail. Trop chargée, elle laisse moins de place pour apprendre.","id":"charge-cognitive","mot":"Charge cognitive","notions":["charge-cognitive"]},{"definition":"Le moment où ce qu'on a appris devient durable, notamment pendant le sommeil et grâce à la répétition.","id":"consolidation","mot":"Consolidation","notions":["quatre-piliers","repetition-espacee"]},{"definition":"Le réseau de l'attention qui permet de tenir malgré les distractions et de freiner une réponse automatique. Très lié au cortex préfrontal.","id":"controle-executif","mot":"Contrôle exécutif","notions":["trois-reseaux","stroop"]},{"definition":"La région à l'avant du cerveau, très liée au contrôle de l'attention. Elle continue de mûrir pendant l'adolescence.","id":"cortex-prefrontal","mot":"Cortex préfrontal","notions":["trois-reseaux"]},{"definition":"Le cycle d'environ 90 minutes décrit par Nathaniel Kleitman. Il est bien établi pendant le sommeil, beaucoup moins pendant l'éveil.","id":"cycle-de-base-repos-activite","mot":"Cycle de base repos-activité","notions":["rythmes-52-17"]},{"definition":"Ce qu'on constate sans rien faire varier. Elle montre un lien, pas une cause.","id":"donnee-d-observation","mot":"Donnée d'observation","notions":["rythmes-52-17"]},{"definition":"L'idée que, quand l'information abonde, l'attention devient rare et donc convoitée.","id":"economie-de-l-attention","mot":"Économie de l'attention","notions":["economie-attention"]},{"definition":"Se poser une question avant d'apprendre la réponse aide à la retenir, même si l'on s'est trompé.","id":"effet-de-pretest","mot":"Effet de prétest","notions":["pretest"]},{"definition":"Nommer la couleur de l'encre d'un mot de couleur qui ne correspond pas prend plus de temps que pour un mot qui correspond.","id":"effet-stroop","mot":"Effet Stroop","notions":["stroop"]},{"definition":"Chercher une réponse dans sa mémoire fait mieux retenir que relire.","id":"effet-test","mot":"Effet test","notions":["effet-test"]},{"definition":"L'idée qu'on se souvient mieux des tâches inachevées. Elle ne se réplique pas.","id":"effet-zeigarnik","mot":"Effet Zeigarnik","notions":["residu"]},{"definition":"Apprendre en agissant : prédire, répondre, expliquer, plutôt qu'écouter passivement.","id":"engagement-actif","mot":"Engagement actif","notions":["quatre-piliers","effet-test"]},{"definition":"La relecture d'une étude par d'autres chercheurs avant sa publication dans une revue scientifique.","id":"evaluation-par-les-pairs","mot":"Évaluation par les pairs","notions":["rythmes-52-17","neuromythes"]},{"definition":"Un problème présenté avec sa solution pas à pas. Il aide les débutants.","id":"exemple-resolu","mot":"Exemple résolu","notions":["charge-cognitive"]},{"definition":"Ce qui attire l'attention sans effort, comme des nuages ou des feuillages : l'une des conditions de la restauration selon Stephen Kaplan.","id":"fascination-douce","mot":"Fascination douce","notions":["restauration"]},{"definition":"Croire savoir parce qu'un texte relu paraît familier.","id":"illusion-de-maitrise","mot":"Illusion de maîtrise","notions":["effet-test"]},{"definition":"Un signal qui annonce où va apparaître une cible. Valide, il fait répondre plus vite ; trompeur, plus lentement.","id":"indice","mot":"Indice","notions":["projecteur"]},{"definition":"Freiner une réponse automatique pour en donner une autre. C'est un effort.","id":"inhibition","mot":"Inhibition","notions":["stroop"]},{"definition":"Ce qui se passe quand deux informations se contredisent, comme le mot ROUGE écrit en bleu.","id":"interference","mot":"Interférence","notions":["stroop"]},{"definition":"Ce qu'on garde en tête et qu'on manipule sur le moment. Elle est limitée.","id":"memoire-de-travail","mot":"Mémoire de travail","notions":["charge-cognitive"]},{"definition":"Une étude qui rassemble les résultats de nombreuses autres pour en tirer une conclusion d'ensemble.","id":"meta-analyse","mot":"Méta-analyse","notions":["repetition-espacee"]},{"definition":"Faire plusieurs choses « à la fois ». Pour des tâches exigeantes, c'est en réalité de l'alternance.","id":"multitache","mot":"Multitâche","notions":["alternance","multitache-numerique"]},{"definition":"Une idée fausse sur le cerveau, souvent tirée d'un vrai résultat mal compris ou exagéré.","id":"neuromythe","mot":"Neuromythe","notions":["neuromythes","styles-apprentissage","poisson-rouge"]},{"definition":"Le réseau de l'attention qui dirige le projecteur vers un endroit, un objet ou une idée.","id":"orientation","mot":"Orientation","notions":["trois-reseaux","projecteur"]},{"definition":"Une attention attirée malgré nous par un bruit, un mouvement ou une vibration.","id":"orientation-imposee","mot":"Orientation imposée","notions":["projecteur","notifications"]},{"definition":"Diriger son attention parce qu'on l'a décidé : on choisit où regarder.","id":"orientation-volontaire","mot":"Orientation volontaire","notions":["projecteur"]},{"definition":"Une courte pause en mouvement : se lever, marcher, s'étirer.","id":"pause-active","mot":"Pause active","notions":["pauses-actives"]},{"definition":"Tout revoir d'un coup, en une fois. Moins efficace qu'espacer.","id":"pratique-massee","mot":"Pratique massée","notions":["repetition-espacee"]},{"definition":"L'image de Michael Posner : l'attention éclaire une partie de ce qui nous entoure, et peut se déplacer sans que les yeux bougent.","id":"projecteur-attentionnel","mot":"Projecteur attentionnel","notions":["projecteur"]},{"definition":"Ce qui aide un débutant peut gêner quelqu'un de plus avancé.","id":"renversement-de-l-expertise","mot":"Renversement de l'expertise","notions":["charge-cognitive"]},{"definition":"Revoir une notion plusieurs fois, en espaçant de plus en plus les révisions.","id":"repetition-espacee","mot":"Répétition espacée","notions":["repetition-espacee","effet-test"]},{"definition":"Refaire une étude pour vérifier que son résultat tient. Un résultat qui ne se réplique pas n'est pas établi.","id":"replication","mot":"Réplication","notions":["residu","notifications","restauration"]},{"definition":"La part de l'attention qui reste accrochée à une tâche inachevée quand on passe à la suivante.","id":"residu-attentionnel","mot":"Résidu attentionnel","notions":["residu"]},{"definition":"L'idée que certains environnements, surtout naturels, rechargent l'attention qu'on dirige.","id":"restauration-attentionnelle","mot":"Restauration attentionnelle","notions":["restauration"]},{"definition":"Savoir vite qu'on s'est trompé, et pourquoi. C'est l'un des quatre piliers de l'apprentissage.","id":"retour-sur-l-erreur","mot":"Retour sur l'erreur","notions":["quatre-piliers"]},{"definition":"Des pensées qui tournent en boucle. Ramener l'attention vers l'extérieur les interrompt.","id":"rumination","mot":"Rumination","notions":["ancrage-54321"]},{"definition":"Une question posée à un moment imprévu (« À quoi pensiez-vous ? ») pour mesurer le vagabondage.","id":"sonde","mot":"Sonde","notions":["vagabondage"]},{"definition":"Deux inspirations par le nez, la seconde courte, puis une longue expiration par la bouche.","id":"soupir-cyclique","mot":"Soupir cyclique","notions":["soupir-cyclique"]},{"definition":"L'idée qu'on apprend mieux selon son profil (visuel, auditif, kinesthésique). C'est un neuromythe.","id":"styles-d-apprentissage","mot":"Styles d'apprentissage","notions":["styles-apprentissage"]},{"definition":"Le fait qu'un entraînement améliore aussi autre chose que l'exercice entraîné. L'« entraînement cérébral » transfère peu.","id":"transfert","mot":"Transfert","notions":["stroop"]},{"definition":"Le moment où l'esprit quitte ce qu'on est en train de faire pour penser à autre chose.","id":"vagabondage-de-l-esprit","mot":"Vagabondage de l'esprit","notions":["vagabondage","mythe-10-minutes"]}],"guides":[{"etapes":[{"notions":["pretest"],"texte":"Avant de lire un chapitre, essayez de répondre aux questions de fin de chapitre. Même raté, cet essai aide à retenir, si la bonne réponse arrive vite après.","titre":"Se poser les questions d'abord"},{"notions":["projecteur"],"texte":"Titres, schémas, résumé : vous saurez où poser votre attention pendant la lecture.","titre":"Parcourir avant de lire"},{"notions":["charge-cognitive"],"texte":"Notez les consignes plutôt que de les garder en tête. Retirez l'inutile, pas le difficile.","titre":"Une chose à la fois"},{"notions":["styles-apprentissage"],"texte":"Dessinez ou complétez un schéma de ce que vous lisez : combiner mots et images aide tout le monde, quel que soit son « profil ».","titre":"Associer un schéma"},{"notions":["effet-test"],"texte":"Écrivez de mémoire ce que vous avez retenu. Relire donne l'illusion de savoir ; chercher dans sa mémoire fait retenir.","titre":"Fermer le livre et rappeler"},{"notions":["quatre-piliers"],"texte":"Comparez aussitôt avec le cours et reprenez ce que vous avez raté : une erreur signalée vite se corrige.","titre":"Corriger vite"},{"notions":["repetition-espacee"],"texte":"Pour un examen dans un mois : revoir après un jour, une semaine, puis deux semaines. Un peu d'oubli entre deux révisions, c'est justement ce qui aide.","titre":"Espacer les révisions"},{"notions":["quatre-piliers"],"texte":"C'est pendant le sommeil que se consolide ce qu'on a appris : la nuit fait partie de la révision.","titre":"Dormir"}],"id":"reviser","quand":"Pour un examen, un concours, une langue : tout ce qu'on veut retenir longtemps.","symbole":"graduationcap","titre":"Réviser pour retenir"},{"etapes":[{"notions":["trois-reseaux"],"texte":"Écrivez en une ligne ce que vous allez faire : c'est là que pointera votre projecteur.","titre":"Nommer une seule tâche"},{"notions":["trois-reseaux"],"texte":"Fatigué, votre « alerte » baisse : gardez la tâche la plus exigeante pour un moment où vous êtes en forme.","titre":"Choisir le bon moment"},{"notions":["notifications"],"texte":"Mode silencieux ou mode avion. Une notification perturbe, même sans la regarder.","titre":"Téléphone hors de vue"},{"notions":["multitache-numerique"],"texte":"Onglets, messageries, fenêtres : ce qui n'est pas ouvert ne tente pas.","titre":"Fermer ce qui est sans rapport"},{"notions":["alternance"],"texte":"Tous les mails d'un coup, à un moment prévu, plutôt que de les intercaler.","titre":"Regrouper les petites tâches"},{"notions":["alternance"],"texte":"Si vous travaillez en musique, choisissez-la sans paroles : des paroles gênent la lecture.","titre":"Musique sans paroles"},{"notions":["rythmes-52-17"],"texte":"Fixez-vous une heure de fin : savoir quand on s'arrête aide à tenir. Testez votre rythme une semaine.","titre":"Annoncer la fin"},{"notions":["vagabondage"],"texte":"Remarquer qu'on était ailleurs, puis revenir, c'est déjà reprendre la main.","titre":"Revenir sans se juger"},{"notions":["residu"],"texte":"Avant de vous arrêter, écrivez en une phrase ce que vous ferez ensuite : la tâche vous laissera partir.","titre":"Noter où vous en êtes"}],"id":"seance","quand":"Pour une tâche exigeante : rédiger, résoudre, apprendre, préparer un cours.","symbole":"scope","titre":"Une séance de travail concentrée"},{"etapes":[{"notions":["residu"],"texte":"Notez où vous en êtes, rangez, respirez : un court rituel aide à quitter la tâche.","titre":"Fermer la porte"},{"notions":["pauses-actives"],"texte":"Deux minutes debout : marchez, étirez-vous. Les pauses en mouvement augmentent ensuite le temps passé concentré.","titre":"Se lever"},{"notions":["restauration"],"texte":"Une fenêtre, un arbre, une rue, plutôt que de faire défiler un écran, qui sollicite encore l'attention.","titre":"Regarder dehors"},{"notions":["soupir-cyclique"],"texte":"Si vous avez besoin de vous poser : une minute de soupir cyclique.","titre":"Respirer"},{"notions":["pauses-actives"],"texte":"Une pause courte et annoncée relance mieux qu'une pause qui s'éternise sur un écran.","titre":"Reprendre à l'heure"}],"id":"pause","quand":"Toutes les heures environ, ou quand vous sentez que vous décrochez.","symbole":"figure.walk","titre":"Faire une vraie pause"},{"etapes":[{"notions":["economie-attention","poisson-rouge"],"texte":"Votre attention n'est pas cassée : le cerveau n'a pas changé, l'environnement sollicite davantage. C'est là qu'on agit le plus facilement.","titre":"Regarder l'environnement d'abord"},{"notions":["notifications"],"texte":"Désactivez celles des applications qui n'ont rien d'urgent.","titre":"Trier les notifications"},{"notions":["economie-attention"],"texte":"Choisir ce qui mérite votre attention est une décision : prenez-la avant d'ouvrir une application, pas après.","titre":"Décider avant d'ouvrir"},{"notions":["projecteur"],"texte":"Une vibration oriente votre attention sans votre accord : posez le téléphone hors de portée.","titre":"Éloigner ce qui vibre"},{"notions":["stroop"],"texte":"Résister à une distraction fatigue. La supprimer coûte moins que la freiner sans cesse.","titre":"Supprimer plutôt que résister"},{"notions":["multitache-numerique"],"texte":"En cours ou en réunion, un écran ouvert sur autre chose coûte aussi à ceux qui sont à côté.","titre":"Un écran, un sujet"}],"id":"ecrans","quand":"Quand vous avez l'impression de ne plus savoir vous concentrer.","symbole":"bell.slash","titre":"Reprendre la main sur les écrans"},{"etapes":[{"notions":["notifications"],"texte":"Rien ne viendra déplacer votre attention au mauvais moment.","titre":"Mode avion"},{"notions":["effet-test"],"texte":"Sans vos notes, redites-vous les idées clés. Relire en dernière minute donne l'illusion de savoir.","titre":"Rappeler plutôt que relire"},{"notions":["soupir-cyclique"],"texte":"Deux inspirations par le nez, une longue expiration par la bouche : un outil pour se poser.","titre":"Une minute de soupir cyclique"},{"notions":["ancrage-54321"],"texte":"Cinq choses que vous voyez, quatre sons, trois contacts, deux odeurs, un goût.","titre":"Le 5-4-3-2-1 si ça s'emballe"},{"notions":["soupir-cyclique","ancrage-54321"],"texte":"Si un exercice de respiration vous met mal à l'aise, respirez normalement. En cas de détresse, parlez-en à un professionnel de santé.","titre":"Ne rien forcer"}],"id":"epreuve","quand":"Dans l'heure qui précède, quand le trac monte.","symbole":"figure.mind.and.body","titre":"Avant un examen, un oral, un entretien"},{"etapes":[{"notions":["pretest"],"texte":"Notez ce que vous pensez qu'on va conclure : se poser la question avant aide à retenir la réponse.","titre":"Deviner avant"},{"notions":["vagabondage","mythe-10-minutes"],"texte":"Prenez des notes, reformulez : l'écoute active ramène l'esprit.","titre":"Écouter en écrivant"},{"notions":["vagabondage"],"texte":"Pendant l'écoute, demandez-vous ce que vous en ferez : une question garde l'esprit présent.","titre":"Se poser des questions"},{"notions":["multitache-numerique"],"texte":"Ce qui s'ouvre à côté vous coûte, et coûte à vos voisins.","titre":"Un seul écran, sur le sujet"},{"notions":["mythe-10-minutes"],"texte":"Aucune minuterie ne sonne : remarquez quand vous décrochez, et changez d'activité à ce moment-là.","titre":"Repérer quand vous décrochez"},{"notions":["vagabondage"],"texte":"Vous étiez ailleurs ? Le remarquer, puis revenir, c'est déjà reprendre la main.","titre":"Revenir"}],"id":"ecouter","quand":"Quand il faut écouter longtemps, sans intervenir.","symbole":"ear","titre":"Suivre un cours ou une réunion longue"},{"etapes":[{"notions":["neuromythes","mythe-10-minutes"],"texte":"Qui l'a montré, et où est-ce publié ? Un chiffre qui circule de livre en livre sans source est suspect.","titre":"Demander la source"},{"notions":["poisson-rouge","rythmes-52-17"],"texte":"Le « poisson rouge » venait d'un rapport marketing ; le « 52/17 », d'une application de suivi du temps.","titre":"Remonter à l'origine"},{"notions":["rythmes-52-17"],"texte":"Une étude publiée dans une revue a été relue par d'autres chercheurs ; un billet de blog, non.","titre":"Vérifier la publication"},{"notions":["rythmes-52-17"],"texte":"Observer que les plus productifs font des pauses ne montre pas que ce rythme cause la productivité.","titre":"Distinguer lien et cause"},{"notions":["residu","notifications"],"texte":"Un résultat qui ne se réplique pas n'est pas établi : c'est le cas de l'effet Zeigarnik, et du téléphone qui « viderait le cerveau ».","titre":"Chercher les réplications"},{"notions":["neuromythes","pauses-actives"],"texte":"Une méthode qui promet d'« activer » une partie du cerveau, ou un programme vendu « basé sur le cerveau », mérite une double vérification.","titre":"Se méfier des promesses"},{"notions":["neuromythes"],"texte":"Même les passionnés de neurosciences croient beaucoup de neuromythes : en savoir beaucoup ne protège pas.","titre":"Rester humble"}],"id":"verifier","quand":"Devant un chiffre, une méthode ou un titre « basé sur le cerveau ».","symbole":"magnifyingglass","titre":"Vérifier une affirmation sur le cerveau"}],"fiches":[{"aEssayer":[{"notion":"trois-reseaux","texte":"Avant de travailler, nommez une seule tâche : c'est là que pointera le projecteur."},{"notion":"projecteur","texte":"Éloignez ce qui capte malgré vous, comme une vibration de téléphone, plutôt que de lutter contre."},{"notion":"vagabondage","texte":"Pendant une vidéo ou une réunion longue, prenez des notes ou posez-vous une question."}],"chapitre":"fonctionnement","chiffres":[{"notion":"cecite","texte":"56 % des participants ne voient pas le gorille quand ils comptent des passes de basket (1999)."},{"notion":"cecite","texte":"6 % seulement remarquent une croix noire en suivant des formes blanches, contre 94 % quand elle est blanche (2001)."},{"notion":"vagabondage","texte":"46,9 % du temps éveillé, l'esprit est ailleurs, chez 2 250 adultes interrogés au hasard de leur journée (2010)."},{"notion":"projecteur","texte":"En 1980, un indice sur l'endroit où regarder fait gagner quelques dizaines de millisecondes ; un indice trompeur en fait perdre."}],"essentiel":[{"notion":"trois-reseaux","texte":"L'attention n'est pas une capacité unique : trois réseaux travaillent ensemble, l'alerte, l'orientation et le contrôle."},{"notion":"projecteur","texte":"Elle se déplace comme un projecteur, même sans bouger les yeux. On la dirige, ou elle est attirée malgré nous."},{"notion":"stroop","texte":"Freiner un automatisme, comme la lecture, est un effort : il fatigue au fil de la journée."},{"notion":"cecite","texte":"On voit ce qu'on cherche : un objet bien visible peut passer inaperçu."},{"notion":"vagabondage","texte":"L'esprit quitte souvent la tâche, et davantage pendant une écoute longue et passive."}],"pieges":[{"notion":"trois-reseaux","texte":"Les trois réseaux ne sont pas trois boutons : c'est un modèle, et ils interagissent en permanence."},{"notion":"cecite","texte":"Ceux qui voient l'objet inattendu ne sont pas « plus attentifs » : ils ne comptaient pas mieux que les autres."},{"notion":"stroop","texte":"S'entraîner au Stroop améliore… le Stroop : l'« entraînement cérébral » transfère peu vers la vie réelle."},{"notion":"vagabondage","texte":"Vagabonder n'est pas toujours négatif : cela sert aussi à planifier et à créer."}]},{"aEssayer":[{"notion":"alternance","texte":"Regroupez les tâches semblables, tous les mails d'un coup, plutôt que de les intercaler."},{"notion":"residu","texte":"Avant de passer à autre chose, notez en une phrase où vous en êtes et ce que vous ferez ensuite."},{"notion":"notifications","texte":"Pendant un travail exigeant : mode silencieux ou mode avion, et téléphone hors de vue."}],"chapitre":"ecrans","chiffres":[{"notion":"multitache-numerique","texte":"11 % de moins au test pour ceux qui font autre chose sur leur ordinateur, et 17 % de moins pour leurs voisins (2013)."},{"notion":"notifications","texte":"En 2015, recevoir un appel ou un message sans y répondre fait faire plus d'erreurs, autant qu'utiliser son téléphone."},{"notion":"residu","texte":"En 2018, écrire en une phrase où l'on reprendra réduit le résidu attentionnel."},{"notion":"economie-attention","texte":"En 1971, Herbert Simon écrit qu'une abondance d'information crée une pauvreté d'attention."}],"essentiel":[{"notion":"alternance","texte":"Faire deux tâches exigeantes « en même temps », c'est alterner : chaque bascule coûte du temps et des erreurs."},{"notion":"residu","texte":"Une tâche laissée inachevée garde une partie de l'attention : c'est le résidu attentionnel."},{"notion":"multitache-numerique","texte":"Faire autre chose sur un écran pendant un cours pénalise celui qui le fait, et ses voisins."},{"notion":"notifications","texte":"Une notification perturbe une tâche exigeante, même sans la regarder."},{"notion":"economie-attention","texte":"Quand l'information abonde, l'attention devient rare, et beaucoup de produits sont conçus pour la capter."}],"pieges":[{"notion":"alternance","texte":"Marcher et parler se combinent bien : c'est entre deux activités exigeantes que ça coince."},{"notion":"notifications","texte":"Que la simple présence du téléphone « vide le cerveau » : les réplications sont discutées, on ne peut pas l'affirmer."},{"notion":"residu","texte":"L'« effet Zeigarnik » (mieux se souvenir de ce qui est inachevé) ne se réplique pas."},{"notion":"economie-attention","texte":"Votre attention n'est pas cassée : le cerveau n'a pas changé en une génération, l'environnement sollicite davantage."}]},{"aEssayer":[{"notion":"neuromythes","texte":"Devant une affirmation sur le cerveau, demandez la source, et vérifiez qu'elle est publiée."},{"notion":"styles-apprentissage","texte":"Choisissez la forme selon ce que vous apprenez : une carte se regarde, une langue s'écoute, un geste se pratique."},{"notion":"rythmes-52-17","texte":"Choisissez un rythme de travail qui vous convient, et testez-le une semaine plutôt que de suivre un chiffre."}],"chapitre":"idees-recues","chiffres":[{"notion":"styles-apprentissage","texte":"93 % des enseignants interrogés au Royaume-Uni et 96 % aux Pays-Bas croyaient aux styles d'apprentissage (2012)."},{"notion":"neuromythes","texte":"242 enseignants croient en moyenne 49 % des neuromythes, alors qu'ils répondent juste à environ 70 % des questions générales."},{"notion":"mythe-10-minutes","texte":"« L'attention chute après 10 à 15 minutes » : les études citées ne le soutiennent pas (2007, 2016)."},{"notion":"poisson-rouge","texte":"« 8 secondes » : popularisé en 2015 par un rapport marketing ; une enquête de la BBC (2017) n'a trouvé aucune étude derrière."},{"notion":"rythmes-52-17","texte":"« 52 minutes puis 17 de pause » : des données d'une application de suivi du temps (2014), jamais publiées dans une revue."}],"essentiel":[{"notion":"styles-apprentissage","texte":"Apprendre selon son « style » (visuel, auditif, kinesthésique) n'améliore pas l'apprentissage."},{"notion":"mythe-10-minutes","texte":"Aucune horloge ne fait chuter l'attention à heure fixe ; l'esprit vagabonde surtout pendant une écoute longue et passive."},{"notion":"poisson-rouge","texte":"La comparaison avec le poisson rouge n'a aucune source scientifique."},{"notion":"rythmes-52-17","texte":"Les cycles de 90 minutes et le « 52/17 » sont peu prouvés pendant la journée ; faire des pauses, lui, est solide."},{"notion":"neuromythes","texte":"Même les passionnés de neurosciences croient beaucoup de neuromythes."}],"pieges":[{"notion":"styles-apprentissage","texte":"Chacun a des préférences, c'est vrai ; mais s'y plier n'aide pas à apprendre."},{"notion":"mythe-10-minutes","texte":"Le bon message n'est pas « tout découper en tranches », mais « varier »."},{"notion":"rythmes-52-17","texte":"Observer que les plus productifs font des pauses ne montre pas que ce rythme cause la productivité."},{"notion":"neuromythes","texte":"Plus de connaissances générales sur le cerveau prédit davantage de croyance aux neuromythes."}]},{"aEssayer":[{"notion":"effet-test","texte":"Après avoir lu, fermez le livre et écrivez ce dont vous vous souvenez."},{"notion":"repetition-espacee","texte":"Pour un examen dans un mois : revoir après un jour, une semaine, puis deux semaines."},{"notion":"pretest","texte":"Avant de lire un chapitre, essayez de répondre aux questions de fin de chapitre."}],"chapitre":"apprendre","chiffres":[{"notion":"effet-test","texte":"Une semaine après, 61 % retenus en se testant, contre 40 % en relisant (2006)."},{"notion":"repetition-espacee","texte":"839 comparaisons dans 317 expériences : espacer bat masser (2006)."},{"notion":"pretest","texte":"Cinq expériences montrent l'effet de prétest, même pour les questions ratées au départ (2009)."},{"notion":"quatre-piliers","texte":"Stanislas Dehaene fait en 2018 la synthèse des sciences cognitives en quatre piliers."}],"essentiel":[{"notion":"quatre-piliers","texte":"On apprend grâce à quatre piliers : l'attention, l'engagement actif, le retour sur l'erreur et la consolidation."},{"notion":"effet-test","texte":"Chercher dans sa mémoire fait mieux retenir que relire, surtout à long terme."},{"notion":"pretest","texte":"Se poser une question avant d'apprendre la réponse aide à la retenir, même quand on s'est trompé."},{"notion":"charge-cognitive","texte":"La mémoire de travail est limitée : ce qui la surcharge laisse moins de place pour apprendre."},{"notion":"repetition-espacee","texte":"Revoir plusieurs fois, en espaçant, fait bien mieux retenir que tout revoir d'un coup."}],"pieges":[{"notion":"effet-test","texte":"Relire donne une illusion de maîtrise : le texte paraît familier, donc « su »."},{"notion":"repetition-espacee","texte":"Espacer paraît moins efficace sur le moment, parce qu'on a un peu oublié : c'est justement ce qui aide."},{"notion":"charge-cognitive","texte":"Ce qui aide un débutant peut gêner quelqu'un de plus avancé : c'est le renversement de l'expertise."},{"notion":"charge-cognitive","texte":"Retirez l'inutile, pas le difficile : la difficulté qui fait réfléchir est utile."}]},{"aEssayer":[{"notion":"pauses-actives","texte":"Toutes les heures environ, levez-vous deux minutes, marchez ou étirez-vous, puis reprenez."},{"notion":"soupir-cyclique","texte":"Avant une tâche exigeante ou après une contrariété : une minute de soupir cyclique."},{"notion":"ancrage-54321","texte":"Avant un examen, un entretien ou une prise de parole : deux minutes de 5-4-3-2-1."}],"chapitre":"recentrer","chiffres":[{"notion":"restauration","texte":"Après 50 minutes de promenade dans un parc, de meilleures performances d'attention qu'en ville (2008)."},{"notion":"restauration","texte":"Une étude de 2023 trouve un effet de la nature sur l'humeur, mais pas sur la concentration."},{"notion":"soupir-cyclique","texte":"108 adultes, un mois : le soupir cyclique donne la plus forte amélioration de l'humeur (2023)."},{"notion":"pauses-actives","texte":"En 2006, après de courtes activités physiques en classe, les élèves passent plus de temps concentrés."}],"essentiel":[{"notion":"restauration","texte":"L'attention qu'on dirige se fatigue ; les environnements naturels aideraient à la recharger. C'est une piste, pas une certitude."},{"notion":"pauses-actives","texte":"De courtes pauses en mouvement augmentent ensuite le temps passé concentré sur la tâche."},{"notion":"soupir-cyclique","texte":"Le soupir cyclique (deux inspirations par le nez, une longue expiration) est un outil pour se poser."},{"notion":"ancrage-54321","texte":"Le 5-4-3-2-1 ramène dans l'instant quand les pensées s'emballent."}],"pieges":[{"notion":"restauration","texte":"Faire défiler un écran n'est pas une vraie pause : il sollicite encore l'attention."},{"notion":"pauses-actives","texte":"*Brain Gym* est un programme commercial dont les promesses sont des neuromythes."},{"notion":"soupir-cyclique","texte":"Aucun effet du soupir cyclique n'est démontré sur la concentration."},{"notion":"ancrage-54321","texte":"Le 5-4-3-2-1 n'est pas un soin : en cas de détresse, parlez-en à un professionnel de santé."}]}],"references":[{"annee":2023,"auteurs":"Balban, M. Y. et al.","id":"balban-2023","montre":"Sur un mois, cinq minutes par jour de soupir cyclique améliorent davantage l'humeur que la méditation de pleine conscience.","notions":["soupir-cyclique"],"reference":"Balban, M. Y. et al. (2023). Brief structured respiration practices enhance mood and reduce physiological arousal. Cell Reports Medicine, 4(1), 100895.","type":"Expérience"},{"annee":2008,"auteurs":"Berman, M. G., Jonides, J. et Kaplan, S.","id":"berman-2008","montre":"Après 50 minutes de promenade dans un parc, de meilleures performances d'attention qu'après une promenade en ville.","notions":["restauration"],"reference":"Berman, M. G., Jonides, J. et Kaplan, S. (2008). The cognitive benefits of interacting with nature. Psychological Science, 19(12), 1207-1212.","type":"Expérience"},{"annee":2016,"auteurs":"Bradbury, N. A.","id":"bradbury-2016","montre":"La durée d'attention en cours dépend surtout de l'enseignant et de la situation, pas d'une horloge interne.","notions":["mythe-10-minutes"],"reference":"Bradbury, N. A. (2016). Attention span during lectures: 8 seconds, 10 minutes, or more? Advances in Physiology Education, 40, 509-513.","type":"Synthèse"},{"annee":2006,"auteurs":"Cepeda, N. J., Pashler, H., Vul, E., Wixted, J. T. et Rohrer, D.","id":"cepeda-2006","montre":"839 comparaisons dans 317 expériences : espacer bat masser, et l'intervalle idéal grandit avec la durée visée.","notions":["repetition-espacee"],"reference":"Cepeda, N. J., Pashler, H., Vul, E., Wixted, J. T. et Rohrer, D. (2006). Distributed practice in verbal recall tasks. Psychological Bulletin, 132(3), 354-380.","type":"Méta-analyse"},{"annee":2018,"auteurs":"Dehaene, S.","id":"dehaene-2018","montre":"Les quatre piliers de l'apprentissage : l'attention, l'engagement actif, le retour sur l'erreur, la consolidation.","notions":["quatre-piliers"],"reference":"Dehaene, S. (2018). Apprendre ! Les talents du cerveau, le défi des machines. Odile Jacob.","type":"Ouvrage"},{"annee":2012,"auteurs":"Dekker, S., Lee, N. C., Howard-Jones, P. et Jolles, J.","id":"dekker-2012","montre":"Des enseignants passionnés de neurosciences croient en moyenne 49 % des neuromythes, dont les styles d'apprentissage.","notions":["styles-apprentissage","neuromythes"],"reference":"Dekker, S., Lee, N. C., Howard-Jones, P. et Jolles, J. (2012). Neuromyths in education: prevalence and predictors of misconceptions among teachers. Frontiers in Psychology, 3, 429.","type":"Enquête"},{"annee":2014,"auteurs":"DeskTime","id":"desktime-2014","montre":"Les utilisateurs les plus productifs d'une application travaillaient environ 52 minutes, puis s'arrêtaient environ 17.","notions":["rythmes-52-17"],"reference":"DeskTime (2014), analyse publiée sur le blog de l'entreprise, non évaluée par des pairs.","type":"Hors revue"},{"annee":2003,"auteurs":"Kalyuga, S., Ayres, P., Chandler, P. et Sweller, J.","id":"kalyuga-2003","montre":"Ce qui aide un débutant peut gêner quelqu'un de plus avancé : le renversement de l'expertise.","notions":["charge-cognitive"],"reference":"Kalyuga, S., Ayres, P., Chandler, P. et Sweller, J. (2003). The expertise reversal effect. Educational Psychologist, 38(1), 23-31.","type":"Synthèse"},{"annee":1995,"auteurs":"Kaplan, S.","id":"kaplan-1995","montre":"Un environnement restaure l'attention s'il offre une fascination douce, un éloignement du quotidien, une étendue et une compatibilité.","notions":["restauration"],"reference":"Kaplan, S. (1995). The restorative benefits of nature: toward an integrative framework. Journal of Environmental Psychology, 15, 169-182.","type":"Théorie"},{"annee":2010,"auteurs":"Killingsworth, M. A. et Gilbert, D. T.","id":"killingsworth-2010","montre":"Interrogés au hasard de leur journée, des adultes ont l'esprit ailleurs 46,9 % du temps, et se disent alors moins heureux.","notions":["vagabondage"],"reference":"Killingsworth, M. A. et Gilbert, D. T. (2010). A wandering mind is an unhappy mind. Science, 330, 932.","type":"Observation"},{"annee":1982,"auteurs":"Kleitman, N.","id":"kleitman-1982","montre":"Le cycle d'environ 90 minutes est bien établi pendant le sommeil, beaucoup moins pendant l'éveil.","notions":["rythmes-52-17"],"reference":"Kleitman, N. (1982). Basic rest-activity cycle — 22 years later. Sleep, 5(4), 311-317.","type":"Synthèse"},{"annee":2009,"auteurs":"Leroy, S.","id":"leroy-2009","montre":"Laisser une tâche inachevée fait moins bien réussir la suivante : c'est le résidu attentionnel.","notions":["residu"],"reference":"Leroy, S. (2009). Why is it so hard to do my work? Organizational Behavior and Human Decision Processes, 109(2), 168-181.","type":"Expérience"},{"annee":2018,"auteurs":"Leroy, S. et Glomb, T. M.","id":"leroy-2018","montre":"Écrire en une phrase où l'on reprendra réduit le résidu attentionnel.","notions":["residu"],"reference":"Leroy, S. et Glomb, T. M. (2018). Tasks interrupted. Organization Science, 29(3), 380-397.","type":"Expérience"},{"annee":1991,"auteurs":"MacLeod, C. M.","id":"macleod-1991","montre":"Un demi-siècle de recherche : l'effet Stroop est l'un des plus robustes de la psychologie.","notions":["stroop"],"reference":"MacLeod, C. M. (1991). Half a century of research on the Stroop effect. Psychological Bulletin, 109(2), 163-203.","type":"Synthèse"},{"annee":2006,"auteurs":"Mahar, M. T. et al.","id":"mahar-2006","montre":"Après de courtes activités physiques en classe, les élèves passent plus de temps concentrés sur leur travail.","notions":["pauses-actives"],"reference":"Mahar, M. T. et al. (2006). Effects of a classroom-based program on physical activity and on-task behavior. Medicine & Science in Sports & Exercise, 38(12), 2086-2094.","type":"Expérience"},{"annee":2017,"auteurs":"Maybin, S.","id":"maybin-2017","montre":"Aucune étude derrière les « 8 secondes d'attention », ni pour les humains, ni pour les poissons rouges.","notions":["poisson-rouge"],"reference":"Maybin, S. (2017). Busting the attention span myth. BBC News, 10 mars 2017.","type":"Presse"},{"annee":2003,"auteurs":"Monsell, S.","id":"monsell-2003","montre":"Le coût de l'alternance persiste même quand on sait à l'avance quelle tâche arrive.","notions":["alternance"],"reference":"Monsell, S. (2003). Task switching. Trends in Cognitive Sciences, 7(3), 134-140.","type":"Synthèse"},{"annee":2001,"auteurs":"Most, S. B., Simons, D. J., Scholl, B. J., Jimenez, R., Clifford, E. et Chabris, C. F.","id":"most-2001","montre":"Plus un objet inattendu ressemble à ce qu'on ignore, moins on le voit : 6 % remarquent une croix noire, 94 % une croix blanche.","notions":["cecite"],"reference":"Most, S. B., Simons, D. J., Scholl, B. J., Jimenez, R., Clifford, E. et Chabris, C. F. (2001). How not to be seen. Psychological Science, 12(1), 9-17.","type":"Expérience"},{"annee":null,"auteurs":"Pas de référence unique","id":"pas-de-reference-unique","montre":"Une technique d'ancrage de la gestion du stress, cohérente avec ce qu'on sait, mais sans étude contrôlée qui lui soit propre.","notions":["ancrage-54321"],"reference":"Pas de référence unique : technique d'ancrage transmise en thérapie et en gestion du stress.","type":"Pratique"},{"annee":2008,"auteurs":"Pashler, H., McDaniel, M., Rohrer, D. et Bjork, R.","id":"pashler-2008","montre":"Presque aucune étude ne teste vraiment les styles d'apprentissage, et celles qui le font ne trouvent pas qu'enseigner selon le « style » aide.","notions":["styles-apprentissage"],"reference":"Pashler, H., McDaniel, M., Rohrer, D. et Bjork, R. (2008). Learning styles: concepts and evidence. Psychological Science in the Public Interest, 9(3), 105-119.","type":"Synthèse"},{"annee":2012,"auteurs":"Petersen, S. E. et Posner, M. I.","id":"petersen-2012","montre":"Fait le bilan du modèle des trois réseaux, vingt ans après.","notions":["trois-reseaux"],"reference":"Petersen, S. E. et Posner, M. I. (2012). The attention system of the human brain: 20 years after. Annual Review of Neuroscience, 35, 73-89.","type":"Synthèse"},{"annee":1980,"auteurs":"Posner, M. I.","id":"posner-1980","montre":"Un indice valide fait répondre plus vite, un indice trompeur plus lentement : l'attention se déplace sans que les yeux bougent.","notions":["projecteur"],"reference":"Posner, M. I. (1980). Orienting of attention. Quarterly Journal of Experimental Psychology, 32(1), 3-25.","type":"Expérience"},{"annee":1990,"auteurs":"Posner, M. I. et Petersen, S. E.","id":"posner-1990","montre":"Propose le modèle des trois réseaux de l'attention : l'alerte, l'orientation et le contrôle.","notions":["trois-reseaux"],"reference":"Posner, M. I. et Petersen, S. E. (1990). The attention system of the human brain. Annual Review of Neuroscience, 13, 25-42.","type":"Théorie"},{"annee":2009,"auteurs":"Richland, L. E., Kornell, N. et Kao, L. S.","id":"richland-2009","montre":"Répondre à des questions avant de lire fait mieux retenir, même pour les questions ratées au départ.","notions":["pretest"],"reference":"Richland, L. E., Kornell, N. et Kao, L. S. (2009). The pretesting effect: do unsuccessful retrieval attempts enhance learning? Journal of Experimental Psychology: Applied, 15(3), 243-257.","type":"Expérience"},{"annee":2012,"auteurs":"Risko, E. F. et al.","id":"risko-2012","montre":"Pendant un cours vidéo d'une heure, le vagabondage augmente, et ceux qui vagabondent retiennent moins.","notions":["vagabondage"],"reference":"Risko, E. F. et al. (2012). Everyday attention: variation in mind wandering and memory in a lecture. Applied Cognitive Psychology, 26, 234-242.","type":"Observation"},{"annee":2006,"auteurs":"Roediger, H. L. et Karpicke, J. D.","id":"roediger-2006","montre":"Une semaine après, ceux qui se sont testés retiennent 61 %, contre 40 % pour ceux qui ont relu.","notions":["effet-test"],"reference":"Roediger, H. L. et Karpicke, J. D. (2006). Test-enhanced learning: taking memory tests improves long-term retention. Psychological Science, 17(3), 249-255.","type":"Expérience"},{"annee":2001,"auteurs":"Rubinstein, J. S., Meyer, D. E. et Evans, J. E.","id":"rubinstein-2001","montre":"Alterner entre deux tâches coûte du temps, davantage quand elles sont complexes ou peu familières.","notions":["alternance"],"reference":"Rubinstein, J. S., Meyer, D. E. et Evans, J. E. (2001). Executive control of cognitive processes in task switching. Journal of Experimental Psychology: Human Perception and Performance, 27(4), 763-797.","type":"Expérience"},{"annee":2013,"auteurs":"Sana, F., Weston, T. et Cepeda, N. J.","id":"sana-2013","montre":"Faire autre chose sur son ordinateur en cours coûte 11 % au test, et 17 % aux voisins qui voient l'écran.","notions":["multitache-numerique"],"reference":"Sana, F., Weston, T. et Cepeda, N. J. (2013). Laptop multitasking hinders classroom learning for both users and nearby peers. Computers & Education, 62, 24-31.","type":"Expérience"},{"annee":1971,"auteurs":"Simon, H. A.","id":"simon-1971","montre":"« Une abondance d'information crée une pauvreté d'attention » : l'origine de l'économie de l'attention.","notions":["economie-attention"],"reference":"Simon, H. A. (1971). Designing organizations for an information-rich world. Dans M. Greenberger (dir.), Computers, Communications, and the Public Interest. Johns Hopkins Press.","type":"Théorie"},{"annee":2016,"auteurs":"Simons, D. J. et al.","id":"simons-2016","montre":"Les programmes d'« entraînement cérébral » améliorent les exercices entraînés, mais transfèrent peu à la vie réelle.","notions":["stroop"],"reference":"Simons, D. J. et al. (2016). Do « brain-training » programs work? Psychological Science in the Public Interest, 17(3), 103-186.","type":"Synthèse"},{"annee":1999,"auteurs":"Simons, D. J. et Chabris, C. F.","id":"simons-1999","montre":"56 % des participants qui comptent des passes ne voient pas un gorille traverser la scène.","notions":["cecite"],"reference":"Simons, D. J. et Chabris, C. F. (1999). Gorillas in our midst. Perception, 28, 1059-1074.","type":"Expérience"},{"annee":2015,"auteurs":"Stothart, C., Mitchum, A. et Yehnert, C.","id":"stothart-2015","montre":"Recevoir un appel ou un message sans y répondre fait faire plus d'erreurs dans une tâche d'attention.","notions":["notifications"],"reference":"Stothart, C., Mitchum, A. et Yehnert, C. (2015). The attentional cost of receiving a cell phone notification. Journal of Experimental Psychology: Human Perception and Performance, 41(4), 893-897.","type":"Expérience"},{"annee":1935,"auteurs":"Stroop, J. R.","id":"stroop-1935","montre":"Nommer la couleur de l'encre d'un mot de couleur incongruent est bien plus lent que nommer une couleur seule.","notions":["stroop"],"reference":"Stroop, J. R. (1935). Studies of interference in serial verbal reactions. Journal of Experimental Psychology, 18(6), 643-662.","type":"Expérience"},{"annee":1988,"auteurs":"Sweller, J.","id":"sweller-1988","montre":"Chercher par essais et erreurs peut saturer la mémoire de travail ; des exemples résolus aident les débutants.","notions":["charge-cognitive"],"reference":"Sweller, J. (1988). Cognitive load during problem solving: effects on learning. Cognitive Science, 12(2), 257-285.","type":"Expérience"},{"annee":2007,"auteurs":"Wilson, K. et Korn, J. H.","id":"wilson-2007","montre":"Les études à l'origine de la « chute à 10-15 minutes » la soutiennent peu.","notions":["mythe-10-minutes"],"reference":"Wilson, K. et Korn, J. H. (2007). Attention during lectures: beyond ten minutes. Teaching of Psychology, 34(2), 85-89.","type":"Synthèse"}]};
